<?phpnamespace app\api\model;use app\common\model\User as UserModel;use hema\wechat\WxBizDataCrypt;use hema\wechat\Wxapp;use hema\wechat\Wechat as Wx;use hema\alipay\Driver as Alipay;use hema\alipay\engine\AopEncrypt;use think\facade\Cache;use think\facade\Db;/** * 用户模型类 */class User extends UserModel{    /**     * 隐藏字段     */    protected $hidden = [];        /**     * 手机号     */    public function getPhoneAttr($value)    {        if(!empty($value)){            return hide_phone($value);        }        return $value;    }    /**     * 获取用户信息     */    public static function getDetail($user_id)    {	    if($user = self::get($user_id,['address_default'])){            return $user;        }         return false;    }    /**     * H5用户自动注册     */    public function h5Register($browser,$code)    {        //微信       if($browser == 'weixin'){           $wx = new Wx;           if($result = $wx->getAuth($code)){                if($result = $wx->getUserInfo($result['openid'])){                    $userInfo = [                        'wx_open_id' => $result['openid'],                        'is_wechat' => $result['subscribe'],                    ];                    //判断是否 开启UnionID机制                    isset($result['unionid']) && $userInfo['union_id'] = $result['unionid'];                                        if (!$user = $this->where(['wx_open_id' => $userInfo['wx_open_id']])->find()){                        //用户不存在才执行                        $user = $this;                        $userInfo['nickname'] = '微信用户';                                            }else{                        $userInfo['login_count'] = $user['login_count'] + 1;                    }                    $user->save($userInfo);                    return $userInfo['wx_open_id'];                }else{                    $this->error = $wx->getError();                    return false;                }            }else{                $this->error = $wx->getError();                return false;            }        }        //支付宝        if($browser == 'alipay'){            $alipay = new Alipay('aliweb');            if($result = $alipay->systemOauthToken($code)){                if(isset($result['open_id'])){                    $alipay_open_id = $result['open_id'];                }else{                    $alipay_open_id = $result['user_id'];                }                $userInfo = [                    'alipay_open_id' => $alipay_open_id,                ];                if (!$user = $this->where('alipay_open_id',$alipay_open_id)->find()){                    //用户不存在才执行                    $user = $this;                     $userInfo['nickname'] = '支付宝用户';                }else{                    $userInfo['login_count'] = $user['login_count'] + 1;                }                $user->save($userInfo);                return $alipay_open_id;            }else{                $this->error = $alipay->getError();                return false;            }        }        //其它        if($browser == 'other'){            return [                'user_id' => '',                'is_login' => false,            ];        }    }    /**     * 小程序用户自动注册     */    public function autoLogin(array $data)    {        //支付宝        if($data['mp'] == 'alipay'){            //微信登录 (获取session_key)            $alipay = new Alipay('aliapp');            if(!$result = $alipay->systemOauthToken($data['code'])){                $this->error = $alipay->getError();                return false;            }            if(isset($result['open_id'])){                $alipay_open_id = $result['open_id'];            }else{                $alipay_open_id = $result['user_id'];            }            $userInfo = [                'alipay_open_id' => $alipay_open_id,            ];            $filter = $userInfo;        }                //微信        if($data['mp'] == 'weixin'){            //(获取session_key)            $wx = new Wxapp;            if(!$result = $wx->code2Session($data['code'])){                $this->error = $wx->getError();                return false;            }            $userInfo = [                'open_id' => $result['openid'],            ];            $filter = $userInfo;            //判断是否 开启UnionID机制            isset($result['unionid']) && $userInfo['union_id'] = $result['unionid'];        }        if (!$user = $this->where($filter)->find()){            //用户不存在才执行            $user = $this;            if($data['mp'] == 'weixin'){                $userInfo['nickname'] = '微信用户';            }            if($data['mp'] == 'alipay'){                $userInfo['nickname'] = '支付宝用户';            }        }else{            $userInfo['login_count'] = $user['login_count'] + 1;        }        $user->save($userInfo);        $user = $this->where($filter)->find();        $user['is_login'] = !empty($user['phone']);//用户电话不为空则为登录状态        return $user;    }        /**     * 获取用户手机号     */    public function getPhoneNumber($data, $userInfo)    {        $arr = [];//合并用户的数据        //微信        if($data['mp'] == 'weixin'){            // 微信登录 获取session_key            $wx = new Wxapp;            if(!$result = $wx->code2Session($data['code'])){                $this->error = $wx->getError();                return false;            }                        $sessionKey = $result['session_key'];            $encryptedData= $data['encryptedData'];            $iv = $data['iv'];                        $pc = new WxBizDataCrypt($sessionKey);            $errCode = $pc->decryptData($encryptedData,$iv,$result);            if($errCode == 0){                $result = json_decode($result,true);                if(!isset($result['phoneNumber'])){                    $this->error = '获取用户手机号解密错误';                    return false;                }                $phone = $result['phoneNumber'];                $arr['union_id'] = $userInfo->union_id;                $arr['open_id'] = $userInfo->open_id;            }else{                $this->error = '获取用户手机号解密错误，code：'.$errCode;                return false;            }        }        //支付宝        elseif($data['mp'] == 'alipay'){            $aes_key = Setting::getItem('aliapp')['aes_key'];//获取支付宝秘钥            $de = new AopEncrypt($aes_key);            $result = json_decode($de->decrypt($data['encryptedData']),true);            if(isset($result['code']) and $result['code'] != '10000'){                $this->error = 'code：' . $result['subCode'] . '，msg：' . $result['subMsg'];                return false;            }            $phone = $result['mobile'];            $arr['alipay_open_id'] = $userInfo->alipay_open_id;        }        //判断该手机号是否存在        if($user = $this->where(['phone' => $phone])->find()){            //该手机号已存在，则进行合并用户信息            if($user['user_id'] != $userInfo->user_id){                $arr['pay'] = $user['pay']+$userInfo->pay;//累加消费金额                $user->save($arr);//保存合并当前用户的数据                $userInfo->delete();//删除当前用户            }        }else{            //不存在，直接保存手机号            $userInfo->phone = $phone;            $userInfo->save();        }        //重新获取当前用户信息        $user = $this->where(['phone' => $phone])->find();        $user['is_login'] = true;        return $user;    }        /**     * 验证码登录     */    public function checkPhoneCaptcha($data)    {        //手机验证码是否正确        if(is_null(Cache::pull($data['phone'] . '_' . $data['captcha']))){            $this->error = '验证码错误';            return false;         }                //判断当前参数中user_id是否存在        if(isset($data['user_id']) and $data['user_id'] > 0){            //说明是通过正常渠道 使用微信或者支付宝浏览器进行登录访问的            $userInfo = $this->get($data['user_id']);//获取当前用户            $is_user = true;        }else{            $is_user = false;        }        if(!$user = $this->where(['phone' => $data['phone']])->find()){            //该手机号用户不存在才执行            $arr['phone'] = $data['phone'];            if($is_user){                $user =$userInfo;//保存给当前用户            }else{                //新增                $user =$this;                $arr['nickname'] = 'H5用户';            }        }else{            //存在手机号用户，并且存在两条记录，则进行合并当前记录            if($is_user and ($userInfo['user_id'] != $user['user_id'])){                !empty($userInfo['union_id']) && $arr['union_id'] = $userInfo['union_id'];                !empty($userInfo['open_id']) && $arr['open_id'] = $userInfo['open_id'];                !empty($userInfo['wx_open_id']) && $arr['wx_open_id'] = $userInfo['wx_open_id'];                !empty($userInfo['alipay_open_id']) && $arr['alipay_open_id'] = $userInfo['alipay_open_id'];                $arr['pay'] = $userInfo['pay']+$user['pay'];//累加消费金额                $userInfo->delete();//删除当前用户            }            $arr['login_count'] = $user['login_count'] + 1;        }        $user->save($arr);        $user = $this->where(['phone' => $data['phone']])->find();        $user['is_login'] = !empty($user['phone']);//用户电话不为空则为登录状态        return $user;    }        /**     * 开通会员     */    public function openVip()    {        //赠送优惠券        $userCoupon = $this->getGift($this->user_id);        // 开启事务        Db::startTrans();        try {            $this->save(['v' => 1]);//开通会员            // 用户发券            if(sizeof($userCoupon) > 0){                $couponUser = new CouponUser;                $couponUser->saveAll($userCoupon);            }            Db::commit();            return true;        } catch (\Exception $e) {            Db::rollback();        }        return false;    }        /**     * 获取开通会员支付详情 - 微信回调     */    public function payDetail(string $order_no)    {        return Cache::get($order_no);    }    /**     * 付费开通会员 - 微信支付回调     */    public function updatePayStatus($mp, string $transaction_id, array $data)    {		//更新用户会员状态		$user = self::get($data['user_id']);		$user->v = 1;//开通会员		$user->score = ['inc', (int)$data['money']];//增加积分		$user->pay = ['inc', $data['money']];//增加消费金额				//赠送优惠券        $userCoupon = $this->getGift($data['user_id']);        // 开启事务        Db::startTrans();        try {		    $user->save();//开通会员		    //增加消费记录		    /************* 可扩展  ***************/            // 用户发券            if(sizeof($userCoupon) > 0){                $couponUser = new CouponUser;                $couponUser->saveAll($userCoupon);            }            Db::commit();            return true;        } catch (\Exception $e) {            Db::rollback();        }        return false;    }        /**     * 获取开通会员赠品列表     */    private function getGift($user_id)    {        $grade = Setting::getItem('vip');        $gift = $grade['vip'][0]['gift'];//v1会员赠送券列表        $userCoupon = [];        $model = new CouponUser;        foreach ($gift as $item) {            $userCoupon[] = $model->dateTmp($item,$user_id);                 }        return $userCoupon;    }}